// Generates every derived brand asset.
//
// Two sources, both committed at the repo root:
//   "spikeledger current.png"    the app icon sheet  -> square app icon
//   "spikeledger logo update.png" the logo sheet     -> wordmarks
//
// Run: node scripts/generate-pwa-assets.mjs
//
// Rules that keep icons sharp:
//   - every size is resampled straight from the full-resolution master with
//     lanczos3. Nothing is generated by scaling another output, and no
//     browser is ever handed a 512 to squeeze into 32.
//   - platform icons are fully opaque. The icon's own background reaches
//     every corner, so it never lands on a white or grey plate, and iOS,
//     Android and Windows can apply their own shape.

import sharp from "sharp";
import { existsSync, writeFileSync } from "node:fs";
import { mkdir } from "node:fs/promises";
import { BRAND_NAVY, SHEET, extractBrandAssets } from "./extract-brand-assets.mjs";
import { ICON_SHEET, extractAppIcon } from "./extract-app-icon.mjs";

// Deep purple from the app icon's palette: the background behind the mark on
// maskable icons and the Windows tile.
export const ICON_BG = "#4c1d95";
const SPLASH_BG = "#f4f6f9"; // paper, matches the light app shell

// Favicon sizes. Browsers, the Windows taskbar and the Start menu each pick
// one; giving them an exact match means nothing gets resized on the fly.
// 256 is missing on purpose: that size is src/app/icon.png, the Next.js file
// convention, and it is the one Windows takes for a pinned site.
const FAVICON_SIZES = [16, 32, 48, 64, 128, 180, 192, 512];
// Sizes inside favicon.ico, which Windows still reaches for when a site is
// pinned. 256 is the one it uses for large tiles.
const ICO_SIZES = [16, 32, 48, 256];

await mkdir("public/icons", { recursive: true });
await mkdir("public/splash", { recursive: true });

// --- Wordmarks (unchanged by the icon work) -------------------------------
if (existsSync(SHEET)) {
  await extractBrandAssets(SHEET);
} else {
  console.log(`(no logo sheet at "${SHEET}" - reusing the current public/logo-*.png)`);
}

// Header copies at 2x the largest place they are drawn (52px tall), so retina
// screens get real pixels instead of a browser downscale of the master.
const HEADER_LOGO_HEIGHT = 104;
for (const name of ["logo-full", "logo-full-on-dark"]) {
  const out = await sharp(`public/${name}.png`)
    .resize({ height: HEADER_LOGO_HEIGHT, kernel: sharp.kernel.lanczos3 })
    .png()
    .toFile(`public/${name}@2x.png`);
  console.log(`public/${name}@2x.png  ${out.width}x${out.height}`);
}

// --- App icon masters -----------------------------------------------------
const icon = await extractAppIcon(ICON_SHEET);
console.log(`app icon master ${icon.size}x${icon.size} from "${ICON_SHEET}"`);
if (icon.size < 512) {
  console.log(`  note: the sheet's largest icon is ${icon.size}px, so 512 and 384 are upscaled.`);
}

// Optical tuning per size, the way icon sets are normally drawn by hand.
// Below 48px the outer ring eats the few pixels the volleyball needs, so the
// small sizes crop slightly into it and get a light unsharp pass to hold the
// seams and the chart bars. Anything 128 and up is left exactly as drawn.
function tuning(size) {
  if (size <= 16) return { zoom: 0.14, sharpen: 0.5 };
  if (size <= 32) return { zoom: 0.08, sharpen: 0.5 };
  if (size <= 64) return { zoom: 0, sharpen: 0.4 };
  return { zoom: 0, sharpen: 0 };
}

// Every platform icon starts here, always resampled from the master.
function fromMaster(buffer, size, masterSide = icon.size) {
  const { zoom, sharpen } = tuning(size);
  let pipeline = sharp(buffer);
  if (zoom > 0) {
    const inset = Math.round(masterSide * zoom);
    pipeline = pipeline.extract({ left: inset, top: inset, width: masterSide - inset * 2, height: masterSide - inset * 2 });
  }
  pipeline = pipeline
    .resize(size, size, { kernel: sharp.kernel.lanczos3, fit: "fill" })
    .flatten({ background: ICON_BG }); // opaque: no white plate behind the mark
  if (sharpen > 0) pipeline = pipeline.sharpen({ sigma: sharpen });
  return pipeline.png({ compressionLevel: 9 });
}

// --- Favicons -------------------------------------------------------------
for (const size of FAVICON_SIZES) {
  const out = await fromMaster(icon.square, size).toFile(`public/icons/favicon-${size}.png`);
  console.log(`public/icons/favicon-${size}.png  ${out.width}x${out.height}`);
}

// The Next.js file conventions: /icon.png (256, the size Windows picks for a
// pinned site) and /apple-icon.png (180, a full square because iOS rounds the
// corners itself and shows black through transparency).
await fromMaster(icon.square, 256).toFile("src/app/icon.png");
await fromMaster(icon.square, 180).toFile("src/app/apple-icon.png");
console.log("src/app/icon.png  256x256\nsrc/app/apple-icon.png  180x180");

// --- favicon.ico (legacy browsers, Windows pinning) -----------------------
const icoParts = [];
for (const size of ICO_SIZES) {
  icoParts.push({ size, png: await fromMaster(icon.square, size).toBuffer() });
}
const header = Buffer.alloc(6);
header.writeUInt16LE(0, 0); // reserved
header.writeUInt16LE(1, 2); // type: icon
header.writeUInt16LE(icoParts.length, 4);
let offset = 6 + icoParts.length * 16;
const entries = icoParts.map(({ size, png }) => {
  const e = Buffer.alloc(16);
  e.writeUInt8(size >= 256 ? 0 : size, 0); // 0 means 256
  e.writeUInt8(size >= 256 ? 0 : size, 1);
  e.writeUInt8(0, 2); // palette
  e.writeUInt8(0, 3); // reserved
  e.writeUInt16LE(1, 4); // colour planes
  e.writeUInt16LE(32, 6); // bits per pixel
  e.writeUInt32LE(png.length, 8);
  e.writeUInt32LE(offset, 12);
  offset += png.length;
  return e;
});
writeFileSync("src/app/favicon.ico", Buffer.concat([header, ...entries, ...icoParts.map((p) => p.png)]));
console.log(`src/app/favicon.ico  ${ICO_SIZES.join(", ")}`);

// --- Manifest icons -------------------------------------------------------
for (const size of [192, 384, 512]) {
  const out = await fromMaster(icon.square, size).toFile(`public/icons/icon-${size}.png`);
  console.log(`public/icons/icon-${size}.png  ${out.width}x${out.height}`);
}

// Maskable: Android launchers crop these to a circle, squircle or square, so
// the mark sits inside the centre 80% and the icon's background fills the
// rest. The circular version of the artwork survives any of those crops.
for (const size of [192, 512]) {
  const inner = Math.round(size * 0.8);
  const mark = await sharp(icon.circle)
    .resize(inner, inner, { kernel: sharp.kernel.lanczos3, fit: "contain", background: { r: 0, g: 0, b: 0, alpha: 0 } })
    .png()
    .toBuffer();
  await sharp({ create: { width: size, height: size, channels: 4, background: ICON_BG } })
    .composite([{ input: mark, gravity: "centre" }])
    .flatten({ background: ICON_BG })
    .png({ compressionLevel: 9 })
    .toFile(`public/icons/maskable-${size}.png`);
  console.log(`public/icons/maskable-${size}.png  ${size}x${size} (mark at ${inner}px)`);
}

// --- iOS splash screens ---------------------------------------------------
// [cssWidth, cssHeight, dpr] - the PNG is css*dpr, and the layout's
// appleWebApp.startupImage media queries follow the same list.
const DEVICES = [
  [375, 667, 2], // iPhone SE / 8 / 7 / 6s
  [414, 896, 2], // iPhone XR / 11
  [375, 812, 3], // iPhone X / XS / 11 Pro
  [414, 896, 3], // iPhone XS Max / 11 Pro Max
  [390, 844, 3], // iPhone 12 / 13 / 14
  [428, 926, 3], // iPhone 12/13 Pro Max / 14 Plus
  [393, 852, 3], // iPhone 14 Pro / 15 / 16
  [430, 932, 3], // iPhone 14 Pro Max / 15 Pro Max
];

for (const [cw, ch, dpr] of DEVICES) {
  const w = cw * dpr;
  const h = ch * dpr;
  const iconSize = Math.round(w * 0.28);
  const wordmarkWidth = Math.round(w * 0.55);
  // The rounded icon keeps its own corners here: this is our surface, not a
  // platform's, so nothing masks it.
  const mark = await sharp(icon.rounded)
    .resize(iconSize, iconSize, { kernel: sharp.kernel.lanczos3 })
    .png()
    .toBuffer();
  const wordmark = await sharp("public/logo-full.png")
    .resize(wordmarkWidth, null, { kernel: sharp.kernel.lanczos3 })
    .png()
    .toBuffer();
  const wordmarkHeight = (await sharp(wordmark).metadata()).height;
  const gap = Math.round(w * 0.06);
  const blockTop = Math.round((h - (iconSize + gap + wordmarkHeight)) / 2);
  await sharp({ create: { width: w, height: h, channels: 4, background: SPLASH_BG } })
    .composite([
      { input: mark, left: Math.round((w - iconSize) / 2), top: blockTop },
      { input: wordmark, left: Math.round((w - wordmarkWidth) / 2), top: blockTop + iconSize + gap },
    ])
    .png()
    .toFile(`public/splash/apple-splash-${w}-${h}.png`);
  console.log(`public/splash/apple-splash-${w}-${h}.png`);
}

console.log(`Done. Icon background ${ICON_BG}, navy ${BRAND_NAVY}.`);
